class CryptoCoreImpl extends RustOpaque implements CryptoCore {
  // Not to be used by end users
  CryptoCoreImpl.frbInternalDcoDecode(List<dynamic> wire)
      : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
